define('util/adaptSize',['jquery', 'util/capitalize'], function ($, capitalize) {
  'use strict';

  $ = $ && Object.prototype.hasOwnProperty.call($, 'default') ? $['default'] : $;
  capitalize = capitalize && Object.prototype.hasOwnProperty.call(capitalize, 'default') ? capitalize['default'] : capitalize;
  var adaptSize = function () {
    function _resize($elements, dimensions) {
      $elements.each(function () {
        for (var dimension in dimensions) {
          if (Object.prototype.hasOwnProperty.call(dimensions, dimension)) {
            $(this)[dimension]('auto');
          }
        }
      });
      $elements.each(function () {
        for (var dimension in dimensions) {
          if (Object.prototype.hasOwnProperty.call(dimensions, dimension)) {
            dimensions[dimension] = Math.max(Math.floor(dimensions[dimension] || 0), $(this)["outer".concat(capitalize(dimension))]());
          }
        }
      });
      $elements.css(dimensions);
    }
    return {
      width($elements, minWidth) {
        _resize($elements, {
          width: minWidth
        });
      },
      height($elements, minHeight) {
        _resize($elements, {
          height: minHeight
        });
      },
      both($elements, minWidth, minHeight) {
        _resize($elements, {
          height: minHeight,
          width: minWidth
        });
      },
      resetHeight($elements) {
        $elements.height('auto');
      }
    };
  }();
  return adaptSize;
});
