define('loader/configRetry',['i18n', 'css!taoCss/configRetry.css'], __ => {
  'use strict';

  return function () {
    var options = arguments.length > 0 && arguments[0] !== undefined ? arguments[0] : {};
    var overlay = null;
    var modal = null;
    var refreshButton = null;
    var previousFocus = null;
    var keepFocusInside = event => {
      if (event.key !== 'Tab') {
        return;
      }
      event.preventDefault();
      refreshButton.focus();
    };
    var render = () => {
      var container = document.body || document.documentElement;
      var modalBody = document.createElement('div');
      var message = document.createElement('p');
      var buttons = document.createElement('div');
      overlay = document.createElement('div');
      overlay.className = 'modal-bg config-retry-modal-bg';
      modal = document.createElement('div');
      modal.className = 'modal config-retry-modal';
      modal.setAttribute('role', 'alertdialog');
      modal.setAttribute('aria-modal', 'true');
      modal.setAttribute('aria-labelledby', 'config-retry-message');
      modal.addEventListener('keydown', keepFocusInside);
      modalBody.className = 'modal-body';
      message.id = 'config-retry-message';
      message.className = 'message';
      message.textContent = options.message || __('Unable to load the required configuration. Refresh the page to try again.');
      buttons.className = 'buttons';
      refreshButton = document.createElement('button');
      refreshButton.type = 'button';
      refreshButton.className = 'btn-info';
      refreshButton.textContent = options.refreshLabel || __('Refresh');
      refreshButton.addEventListener('click', () => {
        refreshButton.disabled = true;
        if (typeof options.onRefresh === 'function') {
          options.onRefresh();
        } else {
          window.location.reload();
        }
      });
      buttons.appendChild(refreshButton);
      modalBody.appendChild(message);
      modalBody.appendChild(buttons);
      modal.appendChild(modalBody);
      overlay.appendChild(modal);
      container.appendChild(overlay);
    };
    return {
      show() {
        if (!modal) {
          previousFocus = document.activeElement;
          render();
        }
        refreshButton.disabled = false;
        refreshButton.focus();
      },
      destroy() {
        var focusToRestore = previousFocus;
        if (modal) {
          modal.removeEventListener('keydown', keepFocusInside);
        }
        if (modal && modal.parentNode) {
          modal.parentNode.removeChild(modal);
        }
        if (overlay && overlay.parentNode) {
          overlay.parentNode.removeChild(overlay);
        }
        modal = null;
        overlay = null;
        refreshButton = null;
        previousFocus = null;
        if (focusToRestore && typeof focusToRestore.focus === 'function') {
          focusToRestore.focus();
        }
      }
    };
  };
});
