define('util/wrapLongWords',['util/regexEscape'], function (regexEscape) {
  'use strict';

  regexEscape = regexEscape && Object.prototype.hasOwnProperty.call(regexEscape, 'default') ? regexEscape['default'] : regexEscape;
  function getCutTerm(longWord, chunkExp) {
    var cutTerms = longWord.match(chunkExp);
    var i = cutTerms.length;
    var oldFirst = '';
    var newFirst = '';
    var offenders = ['.', ':', ';'];
    while (i--) {
      newFirst = cutTerms[i].charAt(0);
      if (offenders.indexOf(newFirst) > -1) {
        cutTerms[i] = cutTerms[i].substr(1);
      }
      if (offenders.indexOf(oldFirst) > -1) {
        cutTerms[i] = cutTerms[i] + oldFirst;
      }
      oldFirst = newFirst;
    }
    return cutTerms.join(' ');
  }
  function wrapLongWords(str, threshold) {
    str = str.toString().replace(/([\w])</g, '$1 <');
    var chunkExp = new RegExp(".{1,".concat(threshold, "}"), 'g');
    var longWords = str.match(new RegExp("[\\S]{".concat(threshold, ",}"), 'g')) || [];
    var i = longWords.length;
    while (i--) {
      var cut = getCutTerm(longWords[i], chunkExp);
      str = str.replace(new RegExp(regexEscape(longWords[i]), 'g'), cut);
    }
    return str;
  }
  return wrapLongWords;
});
