define('util/clipboard',['jquery', 'core/eventifier'], function ($, eventifier) {
  'use strict';

  $ = $ && Object.prototype.hasOwnProperty.call($, 'default') ? $['default'] : $;
  eventifier = eventifier && Object.prototype.hasOwnProperty.call(eventifier, 'default') ? eventifier['default'] : eventifier;
  var clipboard = eventifier({
    clean() {
      this.copy(' ');
    },
    copy(text) {
      var textAreaToSelContent = document.createElement('textarea');
      textAreaToSelContent.setAttribute('id', 'clipboardCleanerPlugin');
      textAreaToSelContent.value = text;
      textAreaToSelContent.setAttribute('readonly', '');
      textAreaToSelContent.style.position = 'absolute';
      textAreaToSelContent.style.left = '-9999px';
      document.body.appendChild(textAreaToSelContent);
      this.copyFromEl(textAreaToSelContent);
      document.body.removeChild(textAreaToSelContent);
    },
    copyFromEl(elem) {
      var el = elem instanceof $ ? elem.get(0) : elem;
      if (document.body.createTextRange) {
        var textRange = document.body.createTextRange();
        textRange.moveToElementText(el);
        textRange.select();
        textRange.execCommand('Copy');
        this.trigger('copied', {
          srcEl: el
        });
      } else if (window.getSelection && document.createRange) {
        var editable;
        var readOnly;
        if (Object.prototype.hasOwnProperty.call(el, 'contentEditable')) {
          editable = el.contentEditable;
          el.contentEditable = true;
        }
        if (Object.prototype.hasOwnProperty.call(el, 'readOnly')) {
          readOnly = el.readOnly;
          el.readOnly = false;
        }
        var range = document.createRange();
        range.selectNodeContents(el);
        var sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
        if (el.nodeName === 'TEXTAREA' || el.nodeName === 'INPUT') {
          el.select();
        }
        if (el.setSelectionRange && navigator.userAgent.match(/ipad|ipod|iphone/i)) {
          el.setSelectionRange(0, 999999);
        }
        if (Object.prototype.hasOwnProperty.call(el, 'contentEditable')) {
          el.contentEditable = editable;
        }
        if (Object.prototype.hasOwnProperty.call(el, 'readOnly')) {
          el.readOnly = readOnly;
        }
        if (document.queryCommandSupported('copy')) {
          var successful = document.execCommand('copy');
          if (successful) {
            this.trigger('copied', {
              srcEl: elem
            });
          } else {
            this.trigger('copyError', {
              srcEl: elem,
              reason: 'Not Success'
            });
          }
        } else {
          if (!navigator.userAgent.match(/ipad|ipod|iphone|android|silk/i)) {
            this.trigger('copyError', {
              srcEl: elem,
              reason: 'Copy command not supported'
            });
          }
        }
      }
    },
    paste(elem) {
      var el = elem instanceof $ ? elem.get(0) : elem;
      if (window.clipboardData) {
        el.value = window.clipboardData.getData('Text');
        el.innerHTML = window.clipboardData.getData('Text');
      } else if (window.getSelection && document.createRange) {
        if (el.tagName.match(/textarea|input/i) && el.value.length < 1) {
          el.value = ' ';
        } else if (el.innerHTML.length < 1) {
          el.innerHTML = '&nbsp;';
        }
        var editable = el.contentEditable;
        var readOnly = el.readOnly;
        el.contentEditable = true;
        el.readOnly = false;
        var range = document.createRange();
        range.selectNodeContents(el);
        var sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
        if (el.nodeName === 'TEXTAREA' || el.nodeName === 'INPUT') {
          el.select();
        }
        if (el.setSelectionRange && navigator.userAgent.match(/ipad|ipod|iphone/i)) {
          el.setSelectionRange(0, 999999);
        }
        if (document.queryCommandSupported('paste')) {
          var successful = document.execCommand('Paste');
          if (successful) {
            this.trigger('pasted', {
              srcEl: elem
            });
          } else {
            if (navigator.userAgent.match(/android/i) && navigator.userAgent.match(/chrome/i)) {
              this.trigger('pasteError', {
                srcEl: elem,
                reason: 'Extra action required'
              });
              if (el.tagName.match(/textarea|input/i)) {
                el.value = ' ';
                el.focus();
                el.setSelectionRange(0, 0);
              } else {
                el.innerHTML = '';
              }
            } else {
              this.trigger('pasteError', {
                srcEl: elem,
                reason: 'Press CTRL-V to paste'
              });
            }
          }
        } else {
          this.trigger('pasteError', {
            srcEl: elem,
            reason: 'Command paste not supported'
          });
        }
        el.contentEditable = editable;
        el.readOnly = readOnly;
      }
    }
  });
  return clipboard;
});
