define('ui/themeLoader',['jquery', 'lodash'], function ($, _) {
  'use strict';

  $ = $ && Object.prototype.hasOwnProperty.call($, 'default') ? $['default'] : $;
  _ = _ && Object.prototype.hasOwnProperty.call(_, 'default') ? _['default'] : _;
  var prefix = 'custom-theme-';
  var $container = $('head').length ? $('head') : $('body');
  var ns = 'themeloader';
  function triggerThemeChange(themeId) {
    _.delay(() => {
      $(document).trigger("themechange.".concat(ns), [themeId]).trigger('themeapplied', [themeId]);
    }, 200);
  }
  function createStyleSheet(theme) {
    var suffix = theme.id === 'base' ? 'base' : 'theme';
    var type = "".concat(prefix).concat(suffix);
    return $('<link>').attr({
      rel: 'stylesheet',
      type: 'text/css',
      href: theme.path,
      'data-type': type,
      'data-name': theme.name || theme.id,
      'data-id': theme.id
    });
  }
  function getLink(id) {
    return $("link[data-id=\"".concat(id, "\"][data-type^=\"").concat(prefix, "\"]"), $container);
  }
  function isAttached(id) {
    return getLink(id).length > 0;
  }
  function enable($nodes) {
    $nodes.prop('disabled', false).removeProp('disabled').removeAttr('disabled');
  }
  function disable($nodes) {
    return $nodes.prop('disabled', true).attr('disabled', true);
  }
  function themeLoader(config) {
    if (!_.isPlainObject(config)) {
      throw new TypeError('Theme loader configuration is required');
    }
    if (!_.isString(config.base)) {
      throw new TypeError('Theme loader configuration is an object with a base property configuration');
    }
    if (!_.isArray(config.available) || !config.available.length) {
      throw new TypeError('No theme declared in the configuration');
    }
    for (var i in config.available) {
      if (!_.isPlainObject(config.available[i]) || _.isEmpty(config.available[i].id) || _.isEmpty(config.available[i].path)) {
        throw new TypeError('There is a theme that does not contain an id or a path');
      }
    }
    var defaultTheme = config.default || _.head(_.map(config.available, 'id'));
    var activeTheme = defaultTheme;
    var themes = [{
      id: 'base',
      path: config.base,
      name: 'TAO'
    }].concat(config.available);
    var styles = {};
    _.forEach(themes, theme => {
      if (isAttached(theme.id)) {
        styles[theme.id] = getLink(theme.id);
      } else {
        styles[theme.id] = createStyleSheet(theme);
      }
    });
    return {
      load(preload) {
        _.forEach(styles, ($link, id) => {
          if (!isAttached(id)) {
            if (!preload && id === activeTheme) {
              $link.on('load', () => triggerThemeChange(id));
            }
            disable($link);
            $container.append($link);
          }
          if (!preload) {
            if (id !== 'base' && id !== defaultTheme) {
              disable($link);
            } else {
              enable($link);
              activeTheme = id;
              triggerThemeChange(activeTheme);
            }
          }
        });
        return this;
      },
      unload() {
        disable($("link[data-type^=\"".concat(prefix, "\"]"), $container));
        return this;
      },
      change(id) {
        if (_.includes(['base', 'default'], id) && !isAttached(id)) {
          id = defaultTheme;
        }
        if (isAttached(id)) {
          disable($("link[data-type=\"".concat(prefix, "theme\"]"), $container));
          enable(getLink(id));
          activeTheme = id;
          triggerThemeChange(activeTheme);
        }
        return this;
      },
      getActiveTheme() {
        return activeTheme;
      }
    };
  }
  return themeLoader;
});
