define('core/request/flowFactory',['core/error/ApiError', 'core/error/NetworkError', 'core/error/TimeoutError'], function (ApiError, NetworkError, TimeoutError) {
  'use strict';

  ApiError = ApiError && Object.prototype.hasOwnProperty.call(ApiError, 'default') ? ApiError['default'] : ApiError;
  NetworkError = NetworkError && Object.prototype.hasOwnProperty.call(NetworkError, 'default') ? NetworkError['default'] : NetworkError;
  TimeoutError = TimeoutError && Object.prototype.hasOwnProperty.call(TimeoutError, 'default') ? TimeoutError['default'] : TimeoutError;
  function httpRequestFlowFactory(httpRequest, url, options) {
    var flow = Promise.resolve();
    if (options.jwtTokenHandler) {
      flow = flow.then(options.jwtTokenHandler.getToken).then(token => ({
        Authorization: "Bearer ".concat(token)
      })).then(headers => {
        options.headers = Object.assign({}, options.headers, headers);
      });
    }
    flow = flow.then(() => Promise.race([httpRequest(url, options), new Promise((resolve, reject) => {
      setTimeout(() => {
        reject(new TimeoutError('Timeout', options.timeout));
      }, options.timeout);
    })]));
    if (options.jwtTokenHandler) {
      flow = flow.then(response => {
        if (response.status === 401) {
          return options.jwtTokenHandler.refreshToken().then(options.jwtTokenHandler.getToken).then(token => {
            options.headers.Authorization = "Bearer ".concat(token);
            return httpRequest(url, options);
          });
        }
        return Promise.resolve(response);
      });
    }
    var originalResponse;
    var responseCode;
    flow = flow.then(response => {
      originalResponse = response.clone();
      responseCode = response.status;
      if (options.returnOriginalResponse) {
        return originalResponse;
      }
      return response.json().catch(() => ({}));
    }).then(response => {
      if (responseCode === 204) {
        return null;
      }
      if (responseCode >= 200 && responseCode < 300 || response && response.success === true) {
        return response;
      }
      var err;
      if (response.errorCode) {
        err = new ApiError("".concat(response.errorCode, " : ").concat(response.errorMsg || response.errorMessage || response.error), response.errorCode, originalResponse);
      } else {
        err = new NetworkError("".concat(responseCode, " : Request error"), responseCode || 0, originalResponse);
      }
      throw err;
    }).catch(err => {
      if (!err.type) {
        return Promise.reject(new NetworkError(err.message, 0));
      }
      return Promise.reject(err);
    });
    return flow;
  }
  return httpRequestFlowFactory;
});
